count = 0
missed = 0
for pid, (hero, problem, technique) in R.items():
    pattern = re.compile(
        r'(  - product_id: "' + re.escape(pid) + r'".*?)'
        r'    hero_feature: "([^"]*?)"\n'
        r'    problem_solved: "([^"]*?)"\n'
        r'    transferable_technique: "([^"]*?)"',
        re.DOTALL
    )
    match = pattern.search(content)
    if match:
        old_text = match.group(0)
        new_text = (
            match.group(1) +
            '    hero_feature: "' + hero + '"\n' +
            '    problem_solved: "' + problem + '"\n' +
            '    transferable_technique: "' + technique + '"'
        )
        content = content.replace(old_text, new_text, 1)
        count += 1
    else:
        print(f"MISS: {pid}", file=sys.stderr)
        missed += 1

with open(filepath, 'w', encoding='utf-8') as f:
    f.write(content)

print(f"Updated {count} products, missed {missed}")
